begin;set local lock_timeout='3s';set local statement_timeout='60s';
create temporary table q_test(actor uuid,sicurezza_actor uuid,azienda uuid,ordine uuid,hr uuid default gen_random_uuid(),altro_hr uuid default gen_random_uuid(),sub uuid default gen_random_uuid(),operaio uuid default gen_random_uuid(),doc_hr uuid default gen_random_uuid(),doc_privato uuid default gen_random_uuid(),doc_ext uuid default gen_random_uuid(),r1 uuid default gen_random_uuid(),r2 uuid default gen_random_uuid(),r3 uuid default gen_random_uuid(),dati jsonb,fonte jsonb,ricevuta jsonb);
insert into q_test(actor,sicurezza_actor,azienda,ordine,dati)select sp.id,sf.user_id,sf.company_id,o.id,'{"tipologia":"abilitazione","titolo":"TEST PLE","ambito":"TEST PLE semovente","ente":"Ente TEST","validita_dal":"2026-11-01","validita_al":"2027-10-31","motivazione_senza_scadenza":"","limitazioni":"TEST condizioni","riferimento":"TEST lettura diretta","conferma_lettura":true}'::jsonb from public.profiles sp join public.staff_permissions sf on public.has_permission_for_company(sp.id,'can_view_persone',sf.company_id) and sf.can_view_sicurezza_cantiere and not sf.can_view_persone and not public.has_role(sf.user_id,'super_admin'::public.app_role) and not public.has_role(sf.user_id,'company_admin'::public.app_role) and not exists(select 1 from public.multi_company_access m where m.user_id=sf.user_id and m.company_id=sf.company_id and m.status='active' and m.access_role::text='company_admin') join public.orders o on o.company_id=sf.company_id and o.deleted_at is null where public.has_permission_for_company(sp.id,'can_view_persone',sf.company_id) and public.has_permission_for_company(sp.id,'can_view_sicurezza_cantiere',sf.company_id) limit 1;
grant select,update on q_test to authenticated;
do $$begin if not exists(select 1 from q_test) then raise exception 'Fixture qualifiche priva di autore autorizzato';end if;end$$;
select set_config('request.jwt.claims',jsonb_build_object('sub',actor,'role','authenticated')::text,true)from q_test;
insert into public.hr_profili(id,company_id,nome,cognome)select x.id,f.azienda,'TEST QUALIFICA','Omonimo' from q_test f cross join lateral(values(f.hr),(f.altro_hr))x(id);
insert into public.subappaltatori_sicurezza(id,company_id,order_id,ragione_sociale)select sub,azienda,ordine,'TEST QUALIFICHE IMPRESA' from q_test;
insert into public.subappaltatori_operai(id,company_id,subappaltatore_id,nome,cognome,mansione)select operaio,azienda,sub,'TEST QUALIFICA','Omonimo','TEST Addetto' from q_test;
insert into public.hr_documenti(id,company_id,hr_profilo_id,categoria,titolo,ente,data_rilascio,data_scadenza,file_name,file_path,note)select doc_hr,azienda,hr,'corso_sicurezza','TEST PLE originale','TEST ente','2026-11-01','2027-10-31','TEST PLE.pdf',azienda::text||'/'||hr::text||'/qualifica.pdf','TEST NOTA HR RISERVATA' from q_test;
insert into public.hr_documenti(id,company_id,hr_profilo_id,categoria,titolo,file_name,file_path,note)select doc_privato,azienda,hr,'visita_medica','TEST DATO SANITARIO','TEST RISERVATO.pdf',azienda::text||'/'||hr::text||'/privato.pdf','TEST RISERVATO' from q_test;
insert into storage.objects(bucket_id,name,version,metadata)select 'fascicoli-cantiere',azienda::text||'/'||doc_ext::text||'/esterno.pdf','TEST QUALIFICHE 1','{"size":10,"eTag":"TEST"}'::jsonb from q_test;
insert into public.sicurezza_fascicolo(id,company_id,subappaltatore_id,operaio_id,tipo,titolo,stato,file_name,file_path,data_rilascio,data_scadenza)select doc_ext,azienda,sub,operaio,'formazione','TEST PLE esterno','ricevuto','TEST PLE esterno.pdf',azienda::text||'/'||doc_ext::text||'/esterno.pdf','2026-11-01','2027-10-31' from q_test;
insert into storage.objects(bucket_id,name,version,metadata)select 'hr-documenti',file_path,'TEST QUALIFICHE 1','{"size":10,"eTag":"TEST"}' from public.hr_documenti where id in(select doc_hr from q_test union all select doc_privato from q_test);
set local role authenticated;
do $$declare t record;q jsonb;f jsonb;r jsonb;begin select * into t from q_test;
 q:=public.sicurezza_qualifiche_quadro(t.azienda,'hr',t.hr);f:=q->'fonti'->0;
 if jsonb_array_length(q->'fonti')<>1 or q::text like '%TEST NOTA HR RISERVATA%' or q::text like '%TEST DATO SANITARIO%' then raise exception 'ASSERT: fonte sanitaria/nota privata esposta';end if;
 update q_test set fonte=f;
 begin perform public.sicurezza_qualifica_registra(t.r1,t.azienda,'hr',t.altro_hr,null,'riesamina',t.doc_hr,f->'foto'->>'impronta',t.dati,'');raise exception 'ASSERT: fonte dell’omonimo';exception when raise_exception then if sqlerrm like 'ASSERT:%' then raise;end if;end;
 begin perform public.sicurezza_qualifica_registra(t.r1,t.azienda,'hr',t.hr,null,'riesamina',t.doc_privato,f->'foto'->>'impronta',t.dati,'');raise exception 'ASSERT: fonte sanitaria accettata';exception when raise_exception then if sqlerrm like 'ASSERT:%' then raise;end if;end;
 begin perform public.sicurezza_qualifica_registra(t.r1,t.azienda,'hr',t.hr,null,'riesamina',t.doc_hr,f->'foto'->>'impronta',jsonb_set(t.dati,'{conferma_lettura}','false'),'');raise exception 'ASSERT: titolo equivale a verifica';exception when raise_exception then if sqlerrm like 'ASSERT:%' then raise;end if;end;
 begin perform public.sicurezza_qualifica_registra(t.r1,t.azienda,'hr',t.hr,null,'riesamina',t.doc_hr,f->'foto'->>'impronta',jsonb_set(t.dati,'{validita_al}','"2028-01-01"'),'');raise exception 'ASSERT: proroga arbitraria';exception when raise_exception then if sqlerrm like 'ASSERT:%' then raise;end if;end;
 r:=public.sicurezza_qualifica_registra(t.r1,t.azienda,'hr',t.hr,null,'riesamina',t.doc_hr,f->'foto'->>'impronta',t.dati,'');update q_test set ricevuta=r;
 if public.sicurezza_qualifica_registra(t.r1,t.azienda,'hr',t.hr,null,'riesamina',t.doc_hr,f->'foto'->>'impronta',t.dati,'') is distinct from r then raise exception 'ASSERT: retry diverso';end if;
 begin perform public.sicurezza_qualifica_registra(t.r1,t.azienda,'hr',t.hr,null,'riesamina',t.doc_hr,f->'foto'->>'impronta',jsonb_set(t.dati,'{titolo}','"ALTRO"'),'');raise exception 'ASSERT: richiesta riutilizzata';exception when serialization_failure then null;end;
 q:=public.sicurezza_qualifiche_quadro(t.azienda,'esterno',t.operaio);f:=q->'fonti'->0;
 perform public.sicurezza_qualifica_registra(t.r3,t.azienda,'esterno',t.operaio,null,'riesamina',t.doc_ext,f->'foto'->>'impronta',t.dati,'');
 if not(q->>'puo_classificare')::boolean then raise exception 'ASSERT: fonte esterna non selezionabile';end if;
 if has_table_privilege('authenticated','public.sicurezza_qualifiche_addetti','SELECT') or has_function_privilege('authenticated','public.sicurezza_qualifica_fonte(uuid,text,uuid,uuid)','execute') then raise exception 'ASSERT: registro privato esposto';end if;
 begin perform public.sicurezza_qualifiche_quadro(gen_random_uuid(),'hr',t.hr);raise exception 'ASSERT: altra azienda';exception when insufficient_privilege then null;end;
end$$;
reset role;
select set_config('request.jwt.claims',jsonb_build_object('sub',sicurezza_actor,'role','authenticated')::text,true)from q_test;
set local role authenticated;
do $$declare t record;q jsonb;begin select * into t from q_test;
 q:=public.sicurezza_qualifiche_quadro(t.azienda,'hr',t.hr);
 if jsonb_array_length(q->'fonti')<>0 or jsonb_array_length(q->'registrazioni')<>1 or (q->>'puo_classificare')::boolean or q::text like '%hr-documenti%' or q::text like '%qualifica.pdf%' then raise exception 'ASSERT: Sicurezza senza HR riceve originali personali';end if;
 begin perform public.sicurezza_qualifica_registra(gen_random_uuid(),t.azienda,'hr',t.hr,t.r1,'revoca',null,null,null,'TEST senza HR');raise exception 'ASSERT: Sicurezza modifica qualifica interna';exception when insufficient_privilege then null;end;
end$$;
reset role;
-- A single existing non-admin permission row is changed only inside this rolled-back fixture.
update public.staff_permissions set sola_lettura=true where user_id=(select sicurezza_actor from q_test) and company_id=(select azienda from q_test);
set local role authenticated;
do $$declare t record;q jsonb;begin select * into t from q_test;
 q:=public.sicurezza_qualifiche_quadro(t.azienda,'esterno',t.operaio);
 if (q->>'puo_classificare')::boolean then raise exception 'ASSERT: sola lettura classificatore';end if;
 begin perform public.sicurezza_qualifica_registra(gen_random_uuid(),t.azienda,'esterno',t.operaio,t.r3,'revoca',null,null,null,'TEST sola lettura');raise exception 'ASSERT: sola lettura modifica esterno';exception when insufficient_privilege then null;end;
end$$;
reset role;
select set_config('request.jwt.claims',jsonb_build_object('sub',actor,'role','authenticated')::text,true)from q_test;
update storage.objects set version='TEST QUALIFICHE 2' where bucket_id='hr-documenti' and name=(select fonte->>'path'from q_test);
set local role authenticated;
do $$declare t record;q jsonb;f jsonb;r jsonb;begin select * into t from q_test;
 q:=public.sicurezza_qualifiche_quadro(t.azienda,'hr',t.hr);f:=q->'fonti'->0;
 if q->'registrazioni'->0->'fonte_corrente' is distinct from 'false'::jsonb then raise exception 'ASSERT: cambio originale invisibile';end if;
 begin perform public.sicurezza_qualifica_registra(t.r2,t.azienda,'hr',t.hr,t.r1,'riesamina',t.doc_hr,t.fonte->'foto'->>'impronta',t.dati,'');raise exception 'ASSERT: riesame fonte obsoleta';exception when serialization_failure then null;end;
 perform public.sicurezza_qualifica_registra(t.r2,t.azienda,'hr',t.hr,t.r1,'riesamina',t.doc_hr,f->'foto'->>'impronta',t.dati,'');
 begin perform public.sicurezza_qualifica_registra(gen_random_uuid(),t.azienda,'hr',t.hr,t.r1,'revoca',null,null,null,'TEST vecchia revoca');raise exception 'ASSERT: nuova revisione scavalcata';exception when serialization_failure then null;end;
end$$;
reset role;
delete from public.hr_documenti where id=(select doc_hr from q_test);
set local role authenticated;
do $$declare t record;q jsonb;r jsonb;begin select * into t from q_test;
 perform public.sicurezza_qualifica_registra(gen_random_uuid(),t.azienda,'hr',t.hr,t.r2,'revoca',null,null,null,'TEST revoca anche senza originale');
 q:=public.sicurezza_qualifiche_quadro(t.azienda,'hr',t.hr);
 if jsonb_array_length(q->'registrazioni')<>3 or q->'registrazioni'->0->>'stato' is distinct from 'revocata' then raise exception 'ASSERT: storico/revoca persi';end if;
end$$;
reset role;
do $$begin
 begin update public.sicurezza_qualifiche_addetti set motivo='TEST MANOMISSIONE' where id=(select r1 from q_test);raise exception 'ASSERT: storico modificabile';exception when raise_exception then if sqlerrm like 'ASSERT:%' then raise;end if;end;
end$$;
select set_config('request.jwt.claims',jsonb_build_object('sub',gen_random_uuid(),'role','authenticated')::text,true);
set local role authenticated;
do $$declare t record;begin select * into t from q_test;begin perform public.sicurezza_qualifiche_quadro(t.azienda,'hr',t.hr);raise exception 'ASSERT: lettore senza permesso';exception when insufficient_privilege then null;end;end$$;
reset role;
select 'PASS: fonti nominative interne/esterne, esclusione sanitaria, date, revisioni, idempotenza, revoca senza originale, isolamento e storico immutabile (metadata; rollback)' as risultato;
rollback;
